import type { Meta, StoryObj } from "@storybook/vue3";
import { KozmosSpriteIcon } from "../../index";

/**
 * Vue's SpriteIcon: the stories React's has, with the same names and args,
 * each inside the KozmosThemeProvider the Storybook's decorator gives every
 * story. test/parity draws each of React's in both and holds Vue's render to
 * React's. Generated by `port SpriteIcon`; Default drawn by hand.
 */
type Args = Record<string, unknown>;

// Every story React's has draws with its own render, so this one does too.
const meta: Meta<Args> = {
  title: "Vue/Core/Media/SpriteIcon",
  component: KozmosSpriteIcon,
  parameters: { layout: "centered" },
};

export default meta;
type Story = StoryObj<Args>;

// Four cells cut from Pointr's published 10.17.0 light atlas, served beside
// the stories (apps/docs/src/sprite-fixture, as React's Storybook serves
// them). A product passes the atlas's own version-pinned URL.
const SPRITE = "./sprite-fixture/sprite";

/**
 * React's Default: each cell as published, at 16, 20 and 24, its aspect
 * ratio kept, the taller marker cell ("1") narrower than its box. A missing
 * cell keeps an empty box.
 */
export const Default: Story = {
  render: () => ({
    components: { KozmosSpriteIcon },
    setup: () => ({
      sprite: SPRITE,
      sizes: [16, 20, 24],
      names: ["desk", "atm", "auditorium", "1", "not-in-the-atlas"],
    }),
    template: `
      <div style="display: grid; gap: 12px">
        <div
          v-for="size in sizes"
          :key="size"
          style="display: flex; gap: 12px; align-items: center"
        >
          <KozmosSpriteIcon
            v-for="name in names"
            :key="name"
            :sprite="sprite"
            :name="name"
            :size="size"
            :label="name === 'desk' ? 'Desk' : undefined"
          />
        </div>
      </div>
    `,
  }),
};
